  "Agent certificates are issued by the fleet CA. Rotation happens in two phases: the new CA first reaches agents as their certificates are renewed, and only then takes over signing.": "Certyfikaty agentów wystawia CA floty. Rotacja przebiega w dwóch fazach: nowe CA najpierw dociera do agentów przy odnowieniu ich certyfikatów, a dopiero potem przejmuje podpisywanie.",
