  "Alerts by severity across the hosts you can see, without the ones somebody took; the taken, silenced and pending ones counted apart.": "Alerty wg severity na widocznych hostach, bez tych, które ktoś przejął; przejęte, wyciszone i oczekujące liczone osobno.",
