  "Allow groups": "AllowGroups",
  "Allow users": "AllowUsers",
  "Also write the reverse (PTR) record — forgetting it is the usual mistake": "Zapisz też rekord odwrotny (PTR) — jego pominięcie to typowy błąd",
  "An HBAC rule says who may enter which hosts through which services. A rule is declared as a whole and the directory is brought to it; the plan shows the hosts and users it reaches and the diff against the rule of the same name before a second person approves.": "Reguła HBAC mówi, kto może wejść na które hosty przez które usługi. Regułę deklaruje się w całości, a katalog jest do niej doprowadzany; plan pokazuje hosty i użytkowników, do których sięga, oraz diff względem reguły o tej samej nazwie, zanim zatwierdzi ją druga osoba.",
  "An IP address or a host name the panel reaches the host at. It replaces what the connection shows; empty forgets it and the observed address returns.": "Adres IP lub nazwa hosta, pod którą panel dociera do hosta. Zastępuje to, co pokazuje połączenie; pusty zapomina go i wraca adres zaobserwowany.",
  "An RFC 1123 name, lower-case: a label or a fully qualified name.": "Nazwa wg RFC 1123, małymi literami: etykieta albo FQDN.",
  "An absolute path on {host}; it must be empty.": "Ścieżka bezwzględna na {host}; katalog musi być pusty.",
  "An account is created, locked, expired, preserved or given a new password as a change: the plan shows the groups, the hosts reachable through HBAC and the sudo rules, a second person approves it, and every phase keeps its own result. The initial password never reaches the logs.": "Konto jest tworzone, blokowane, wygaszane, zachowywane albo dostaje nowe hasło jako zmiana: plan pokazuje grupy, hosty osiągalne przez HBAC i reguły sudo, druga osoba zatwierdza, a każda faza ma własny wynik. Hasło początkowe nigdy nie trafia do logów.",
  "An agent manages one host. A relay carries the traffic of a site the panel cannot reach directly - it is a separate trust boundary with its own permission and its own certificate kind.": "Agent zarządza jednym hostem. Relay przenosi ruch lokalizacji, do której panel nie dociera bezpośrednio — to osobna granica zaufania z własnym uprawnieniem i własnym rodzajem certyfikatu.",
  "An attempt to limit the damage, with no guarantee of the initial state.": "Próba ograniczenia szkód bez gwarancji stanu początkowego.",
  "An empty list removes every key of the account and can cut off its SSH login.": "Pusta lista usuwa wszystkie klucze konta i może odciąć logowanie SSH.",
  "An identity recovery is under way: no operations and no secrets until the new certificate opens its first session. The old certificate may still connect for a day, so the host can be read.": "Trwa odzyskiwanie tożsamości: bez operacji i sekretów, dopóki nowy certyfikat nie otworzy pierwszej sesji. Stary certyfikat może się jeszcze łączyć przez dobę, żeby dało się hosta odczytać.",
  "An incoming webhook of Slack, or of a service that reads its shape: the body is {text, blocks}.": "Incoming webhook Slacka albo usługi zgodnej z jego formatem: body to {text, blocks}.",
  "An operation that must reach the whole fleet has hosts it cannot reach.": "Operacja, która musi objąć całą flotę, ma hosty, do których nie dotrze.",
  "Anchors the panel put on hosts. During a rotation a host trusts both the old and the new authority; the old one may only be withdrawn once nothing signs with it any more.": "Kotwice, które panel umieścił na hostach. W trakcie rotacji host ufa staremu i nowemu urzędowi naraz; stary można wycofać dopiero, gdy nic już nim nie podpisuje.",
  "Another campaign already works on this host.": "Na tym hoście pracuje już inna kampania.",
  "Another operation holds the resource on the host.": "Inna operacja trzyma zasób na hoście.",
