  "Ask somebody with the scope, or narrow the selector.": "Poproś kogoś z odpowiednim zakresem albo zawęź selektor.",
  "Ask the directory whether a user may use a service on a host. The answer is the directory's verdict, not a guess of the panel.": "Zapytaj katalog, czy użytkownik może użyć usługi na hoście. Odpowiedź to werdykt katalogu, nie domysł panelu.",
