  "At least 8 characters. A host in an isolated site has no other path: it stays offline until a new relay is enrolled.": "Co najmniej 8 znaków. Host w odizolowanej lokalizacji nie ma innej ścieżki: pozostaje offline do rejestracji nowego relaya.",
