  "Automatic remediation: the campaigns this policy orders are approved by this publication and start without a second look. This needs the policy.remediate.auto permission.": "Naprawa automatyczna: kampanie zlecane przez tę politykę są zatwierdzane tą publikacją i startują bez drugiego spojrzenia. Wymaga to uprawnienia policy.remediate.auto.",
