  "Canary is wave zero. The concurrency limit says how many hosts move at once in this change; fleet and site budgets say how much the system carries in total, and a host waiting for capacity says so instead of standing still.": "Canary to fala zero. Limit równoległości mówi, ile hostów rusza naraz w tej zmianie; budżety floty i lokalizacji mówią, ile system uniesie łącznie, a host czekający na pojemność mówi to wprost zamiast stać bez słowa.",
