  "Count available updates without changing host state. On Arch the plan comes from checkupdates, the whole system upgrades at once and the security count is unknown.": "Policz dostępne aktualizacje bez zmiany stanu hosta. Na Archu plan pochodzi z checkupdates, cały system aktualizuje się naraz, a liczba poprawek bezpieczeństwa jest nieznana.",
  "Counted by the agent on its last report.": "Policzone przez agenta przy ostatnim raporcie.",
  "Counted by the inventory cycle; the lists below come from a read.": "Policzone w cyklu inwentaryzacji; listy poniżej pochodzą z odczytu.",
  "Counted from the creation; a host still offline by then is left out with a reason.": "Liczony od utworzenia; host nadal offline po tym czasie zostaje pominięty z podanym powodem.",
  "Counted in the database over the hosts you can see.": "Policzone w bazie po hostach, które widzisz.",
  "Counters": "Liczniki",
  "Counting…": "Liczę…",
  "Coverage": "Pokrycie",
  "Create": "Utwórz",
  "Create a campaign on {n} hosts": "Utwórz kampanię na {n} hostach",
  "Create enrollment token": "Utwórz token enrollmentu",
  "Create group": "Utwórz grupę",
  "Create identity": "Utwórz tożsamość",
  "Create local account": "Utwórz konto lokalne",
  "Create rule": "Utwórz regułę",
  "Create the account with no way in: no key, and the panel sets no password. Somebody will have to add a key before anybody can log in.": "Załóż konto bez żadnej drogi wejścia: bez klucza, a hasła panel nie ustawia. Ktoś będzie musiał dodać klucz, zanim ktokolwiek się zaloguje.",
  "Create the channel": "Utwórz kanał",
  "Create the draft": "Utwórz szkic",
  "Create the repository on the first backup if it does not exist yet": "Utwórz repozytorium przy pierwszej kopii, jeśli jeszcze nie istnieje",
  "Create the schedule": "Utwórz harmonogram",
  "Created": "Utworzono",
  "Created by": "Utworzył",
  "Created since": "Utworzone od",
  "Creating the campaign freezes the snapshot. Nothing changes on any host yet.": "Utworzenie kampanii zamraża snapshot. Na żadnym hoście nic się jeszcze nie zmienia.",
  "Creating…": "Tworzenie…",
  "Credentials cached": "Poświadczenia w cache",
  "Critical": "Krytyczne",
  "Cron entries and systemd timers under one list. Entries created here belong to Flotestro and live in their own files; entries found on the host stay untouched until you adopt them.": "Wpisy crona i timery systemd na jednej liście. Wpisy utworzone tutaj należą do Flotestro i żyją we własnych plikach; wpisy zastane na hoście pozostają nietknięte, dopóki ich nie przejmiesz.",
  "Cron entries and timers, by whether they run and who owns them.": "Wpisy crona i timery: czy działają i kto jest ich właścicielem.",
  "Cron expression": "Wyrażenie crona",
  "Current": "Bieżąca",
  "Current hostname": "Obecny hostname",
  "Current members ({n})": "Obecni członkowie ({n})",
  "Current version": "Bieżąca wersja",
  "Custom": "Własny",
  "DNS": "DNS",
  "DNS servers": "Serwery DNS",
  "DNS servers, comma separated": "Serwery DNS, po przecinku",
  "Daemon": "Demon",
  "Daemon config": "Konfiguracja demona",
  "Dark theme with a green accent": "Ciemny motyw z zielonym akcentem",
  "Dark theme with a peach accent": "Ciemny motyw z brzoskwiniowym akcentem",
  "Dashboard": "Dashboard",
  "Database": "Baza danych",
  "Day of the month": "Dzień miesiąca",
  "Deadline for offline hosts (minutes)": "Deadline dla hostów offline (minuty)",
  "Debian snapshot age": "Wiek snapshotu Debiana",
  "Debian tracker": "Tracker Debiana",
  "Decided by": "Decyzja",
  "Decided by each distribution's own security tracker, because fixes are backported: a version that looks vulnerable upstream may already carry the patch. Upstream feeds can add descriptions and scores later, but they never overrule the vendor.": "Rozstrzyga tracker bezpieczeństwa danej dystrybucji, bo poprawki są backportowane: wersja, która upstream wygląda na podatną, może już mieć łatkę. Feedy upstream mogą później dołożyć opisy i scoring, ale nigdy nie przebijają producenta.",
  "Decision and result": "Decyzja i wynik",
  "Decisions nobody has taken yet.": "Decyzje, których nikt jeszcze nie podjął.",
  "Declared by": "Zgłosił",
  "Decommission host": "Wycofaj hosta",
  "Decommission host…": "Wycofaj hosta…",
  "Default policy (ufw)": "Polityka domyślna (ufw)",
  "Default text size": "Domyślny rozmiar tekstu",
  "Default {n}; at most {max} (a year).": "Domyślnie {n}; maksymalnie {max} (rok).",
  "Define a backup": "Zdefiniuj kopię",
  "Definition": "Definicja",
  "Definition removed. The history of its runs stays.": "Definicja usunięta. Historia jej przebiegów zostaje.",
  "Definition {name} saved. Plan it to read the repository.": "Definicja {name} zapisana. Zaplanuj ją, by odczytać repozytorium.",
  "Degraded": "Zdegradowane",
  "Degraded relays": "Relaye w degradacji",
  "Delete": "Usuń",
  "Delete account": "Usuń konto",
  "Delete from the repository what the retention above no longer keeps": "Usuwaj z repozytorium to, czego powyższa retencja już nie trzyma",
  "Delete the budget {key}?": "Usunąć budżet {key}?",
  "Delete the channel {name}?": "Usunąć kanał {name}?",
  "Delete the group {name}?": "Usunąć grupę {name}?",
  "Delete the policy": "Usuń politykę",
  "Delete the policy and its verdicts? Its campaigns stay.": "Usunąć politykę i jej werdykty? Jej kampanie zostają.",
  "Delete the rule": "Usuń regułę",
  "Delete the rule {name}? Its alerts resolve on the next evaluation.": "Usunąć regułę {name}? Jej alerty zamkną się przy następnej ewaluacji.",
  "Delete the schedule {name}?": "Usunąć harmonogram {name}?",
  "Delivered trail events": "Dostarczone zdarzenia traila",
  "Delivery log": "Log dostarczeń",
  "Delivery queue": "Kolejka doręczeń",
  "Deny groups": "Deny groups",
  "Deny users": "DenyUsers",
  "Dependencies": "Zależności",
  "Deploy": "Wdróż",
  "Deploy a certificate": "Wdróż certyfikat",
  "Deploy certificate": "Wdróż certyfikat",
  "Deploy this plan": "Wdróż ten plan",
  "Deployed": "Wdrożono",
  "Deployments": "Wdrożenia",
  "Deployments from the panel": "Wdrożenia z panelu",
  "Description": "Opis",
  "Deselect": "Odznacz",
