  "Details": "Szczegóły",
  "Detected capabilities": "Wykryte capabilities",
  "Device": "Urządzenie",
  "Devices": "Urządzenia",
  "Devices from the kernel, mounts from mountinfo, persistence from fstab — kept apart on purpose: the file says what should be mounted after a reboot, not what is mounted now.": "Urządzenia z jądra, montowania z mountinfo, trwałość z fstab — celowo osobno: plik mówi, co ma być zamontowane po restarcie, a nie co jest zamontowane teraz.",
  "Difference": "Różnica",
  "Digest {digest} · deploying uses exactly this plan; if the manifest or the images change, the deployment is refused.": "Digest {digest} · wdrożenie używa dokładnie tego planu; jeśli manifest lub obrazy się zmienią, wdrożenie zostanie odrzucone.",
  "Direct roles": "Role bezpośrednie",
  "Directly to the panel": "Bezpośrednio do panelu",
  "Directory": "Katalog",
  "Directory changes": "Zmiany w katalogu",
  "Directory client": "Klient katalogu",
  "Directory connector": "Konektor katalogu",
