  "Disabled": "Wyłączone",
  "Discard changes": "Odrzuć zmiany",
  "Dismiss": "Zamknij",
  "Dispatch rate (envelopes per second)": "Tempo dispatchu (kopert na sekundę)",
  "Dispatch rate (per second)": "Tempo dispatchu (na sekundę)",
