  "Host groups": "Grupy hostów",
  "Host groups are what the access and sudo rules point at, so a host moved into one gains every rule that names the group. The plan lists those rules before a second person approves. Directory host groups and panel groups have separate lifecycles: one is read by SSSD on the hosts, the other by the panel alone.": "Reguły HBAC i sudo wskazują na grupy hostów, więc host przeniesiony do grupy dostaje każdą regułę, która ją wymienia. Plan wypisuje te reguły, zanim druga osoba zatwierdzi. Grupy hostów katalogu i grupy panelu mają osobne cykle życia: jedne czyta SSSD na hostach, drugie tylko panel.",
