  "How each account can be entered, as the host reports it.": "Jak można wejść na każde konto, wg raportu hosta.",
  "How long a rebooted host is waited for before it fails; a host still away when the maintenance window ends fails at once and pauses the campaign.": "Jak długo czekamy na powrót hosta po reboocie, zanim uznamy go za failed; host, który nie wrócił przed końcem maintenance window, dostaje failed od razu i zatrzymuje kampanię (pause).",
  "How long each certificate has left, as the panel judges it.": "Ile zostało każdemu certyfikatowi, wg oceny panelu.",
  "How long one host's task may run; 0 keeps the operation's default of {n} seconds.": "Ile może trwać zadanie na jednym hoście; 0 zostawia domyślne {n} sekund operacji.",
  "How long one host's task may run; 0 keeps the operation's default.": "Ile może trwać zadanie na jednym hoście; 0 zostawia domyślny limit operacji.",
  "How long this class waits before its fair share stops binding.": "Jak długo ta klasa czeka, zanim fair share przestanie ją ograniczać.",
  "How many definitions had their newest successful copy on each day. Empty days in a row are a schedule that stopped, visible before any copy is old enough to turn red.": "Ile definicji miało najnowszą udaną kopię danego dnia. Kilka pustych dni z rzędu to harmonogram, który stanął — widać to, zanim jakakolwiek kopia zestarzeje się do czerwieni.",
  "How many hosts run their plan at the same time.": "Ile hostów wykonuje swój plan równolegle.",
  "How many rows a list loads at once; empty for the panel's default, at most 500.": "Ile wierszy lista ładuje naraz; puste oznacza domyślne ustawienie panelu, najwyżej 500.",
  "How you like the panel. The choices are kept under your identity and follow you to the next browser.": "Jak lubisz mieć ustawiony panel. Wybory są zapisane przy Twojej tożsamości i idą za Tobą do kolejnej przeglądarki.",
