  "No budget is configured. Without one the fleet carries whatever is asked of it; a capacity is set with the API under a key such as global:mutations or site:*:packages.": "Żaden budżet nie jest skonfigurowany. Bez niego flota bierze wszystko, o co ją poproszą; pojemność ustawia się przez API pod kluczem takim jak global:mutations albo site:*:packages.",
  "No budget is configured. Without one the fleet carries whatever is asked of it; set a capacity under a key such as global:mutations or site:*:packages with the button above.": "Nie skonfigurowano żadnego budżetu. Bez niego flota przyjmuje wszystko, o co się ją prosi; pojemność ustawia się przyciskiem powyżej pod kluczem takim jak global:mutations albo site:*:packages.",
  "No campaign closed in the period.": "W tym okresie nie zakończyła się żadna kampania.",
  "No campaign matches the filter.": "Żadna kampania nie pasuje do filtra.",
  "No campaign or policy names this group in its selector.": "Żadna kampania ani polityka nie wskazuje tej grupy w selektorze.",
  "No campaign ordered: report mode, no drift, or a drift nothing can fix.": "Nie zlecono kampanii: tryb raportu, brak driftu albo drift, którego nic nie naprawi.",
