  "No campaigns.": "Brak kampanii.",
  "No certificate is watched on this host yet.": "Na tym hoście nie jest jeszcze obserwowany żaden certyfikat.",
  "No certificate is watched on this host yet. Add a path, or scan the host if certmonger tracks something here.": "Na tym hoście nie jest jeszcze obserwowany żaden certyfikat. Dodaj ścieżkę albo przeskanuj host, jeśli certmonger coś tu śledzi.",
  "No change": "Bez zmian",
  "No channels: the alerts fire and the campaigns end, but nobody is told outside the panel.": "Brak kanałów: alerty odpalają, kampanie się kończą, ale nikt poza panelem o tym nie wie.",
  "No credential lies in the channel: the address of an incoming webhook, the key a webhook is signed with and a mail password go to the secret store the moment they are typed and are never shown back. The form says only whether one is configured and when it was last rotated; an empty field keeps the stored one.": "W kanale nie leży żaden sekret: adres webhooka przychodzącego, klucz podpisujący webhooka i hasło do poczty trafiają do magazynu sekretów w chwili wpisania i nigdy nie są pokazywane z powrotem. Formularz mówi tylko, czy sekret jest ustawiony i kiedy był rotowany; puste pole zachowuje ten zapisany.",
  "No cron entries and no timers on this host.": "Brak wpisów crona i timerów na tym hoście.",
  "No deadline in the windows watched.": "Brak terminów w obserwowanych oknach.",
