  "No further host starts until the campaign is resumed.": "Żaden kolejny host nie startuje, dopóki kampania nie zostanie wznowiona.",
  "No group matches the search.": "Żadna grupa nie pasuje do wyszukiwania.",
  "No groups yet. A campaign can still name hosts by site, environment, tags or a list.": "Nie ma jeszcze grup. Kampania i tak może wskazać hosty po site, środowisku, tagach albo z listy.",
  "No groups.": "Brak grup.",
  "No host answered.": "Żaden host nie odpowiedział.",
  "No host has a backup definition yet. Open a host and describe what to copy, where to and how long it stays.": "Żaden host nie ma jeszcze definicji kopii. Otwórz host i opisz, co kopiować, dokąd i jak długo trzymać.",
  "No host has a finding.": "Żaden host nie ma ustalenia.",
  "No host has an open session through this relay.": "Żaden host nie ma otwartej sesji przez ten relay.",
  "No host has been assessed yet.": "Żaden host nie został jeszcze oceniony.",
  "No host holds a certificate of any authority.": "Żaden host nie trzyma certyfikatu żadnego CA.",
  "No host in this part of the fleet.": "Brak hostów w tej części floty.",
  "No host is enrolled yet": "Żaden host nie jest jeszcze zarejestrowany",
  "No host is left out by name. An excluded host stays in the snapshot as excluded, with the reason and your name next to it.": "Żaden host nie jest pominięty z nazwy. Wykluczony host zostaje w snapshocie jako wykluczony, z powodem i twoją nazwą obok.",
  "No host is started outside the maintenance window, and every host is checked once its change is done. Both go into the fingerprint the approver signs.": "Żaden host nie startuje poza oknem serwisowym, a każdy jest sprawdzany po wykonaniu zmiany. Jedno i drugie wchodzi do fingerprintu, który podpisuje zatwierdzający.",
  "No host matches the filter.": "Żaden host nie pasuje do filtra.",
  "No host matches the filters.": "Żaden host nie pasuje do filtrów.",
  "No host matches these filters.": "Żaden host nie pasuje do tych filtrów.",
  "No host reports a certificate yet. Open a host, watch a path and scan it.": "Żaden host nie raportuje jeszcze certyfikatu. Otwórz host, dodaj ścieżkę do obserwacji i przeskanuj ją.",
  "No host was changed by this campaign; there is nothing to compensate.": "Ta kampania nie zmieniła żadnego hosta; nie ma czego kompensować.",
  "No host will be issued {name} again, at any version. A job that names it will fail at the lease. The metadata and the version history stay; a retirement cannot be undone.": "Żaden host nie dostanie już {name}, w żadnej wersji. Zadanie, które go wskaże, polegnie na dzierżawie. Metadane i historia wersji zostają; wycofania nie da się cofnąć.",
  "No host you can see carries this CVE and no feed describes it.": "Żaden widoczny dla Ciebie host nie ma tego CVE i żaden feed go nie opisuje.",
  "No host you can see carries this CVE.": "Żaden widoczny dla Ciebie host nie ma tego CVE.",
  "No host you may change carries this tag any more; the catalogue is read again.": "Żaden host, który możesz zmieniać, nie nosi już tego tagu; katalog jest odczytywany ponownie.",
  "No host you may read carries a tag. Tags are set on the host page, under Overview.": "Żaden host, który możesz czytać, nie nosi tagu. Tagi nadaje się na stronie hosta, w Przeglądzie.",
  "No identities.": "Brak tożsamości.",
  "No identity matches the filter.": "Żadna tożsamość nie pasuje do filtra.",
  "No identity matches the search.": "Żadna tożsamość nie pasuje do wyszukiwania.",
  "No identity provider is configured in this installation. Access to the panel uses an API token passed in the Authorization header.": "Ta instalacja nie ma skonfigurowanego dostawcy tożsamości. Dostęp do panelu odbywa się tokenem API w nagłówku Authorization.",
  "No installation is waiting for a host right now.": "Żadna instalacja nie czeka teraz na host.",
