  "No jobs.": "Brak zadań.",
  "No key=value tag.": "Brak tagów klucz=wartość.",
  "No line carries a timestamp; see the lines by host below.": "Żadna linia nie ma timestampu; linie per host są poniżej.",
  "No live browser session. Tokens are not sessions.": "Brak aktywnej sesji przeglądarki. Tokeny nie są sesjami.",
  "No live token.": "Brak aktywnego tokenu.",
  "No mappings. Without them nobody gets a role from the identity provider.": "Brak mapowań. Bez nich nikt nie dostanie roli z dostawcy tożsamości.",
  "No measurements.": "Brak pomiarów.",
  "No new hosts start until resumed; work under way finishes on its own.": "Żaden nowy host nie startuje do wznowienia; praca w toku kończy się sama.",
  "No order is placed until it is enabled again; the campaigns it already placed are not touched.": "Do ponownego włączenia żadne zlecenie nie zostanie złożone; kampanie już zlecone pozostają bez zmian.",
