  "No package repository is configured on the panel; replace {url} in the commands with the address of yours.": "Panel nie ma skonfigurowanego repozytorium pakietów; zamień {url} w poleceniach na adres swojego.",
  "No panel-managed authority on any host.": "Brak urzędu zarządzanego przez panel na jakimkolwiek hoście.",
