  "No plan.": "Brak planu.",
  "No platform has been recorded for this host yet.": "Panel nie zapisał jeszcze żadnej platformy tego hosta.",
  "No policy is declared.": "Nie zadeklarowano żadnej polityki.",
  "No policy is declared. Without one the panel reports what the hosts are, not what they should be.": "Nie zadeklarowano żadnej polityki. Bez niej panel raportuje, jakie hosty są, a nie jakie mają być.",
  "No policy selects this host, or none has been evaluated yet.": "Żadna polityka nie wybiera tego hosta albo żadna nie została jeszcze oceniona.",
  "No preserved accounts.": "Brak zachowanych kont.",
  "No query in the result.": "Brak zapytań w wyniku.",
  "No reads yet.": "Brak odczytów.",
  "No recorded events yet.": "Brak zapisanych zdarzeń.",
  "No relay is registered in this installation.": "W tej instalacji nie ma zarejestrowanego relaya.",
  "No relay is registered. A relay is added from the add-host screen with a relay token; a site that sees the panel directly needs none.": "Brak zarejestrowanego relaya. Relay dodaje się z ekranu dodawania hosta tokenem relaya; lokalizacja, która widzi panel bezpośrednio, nie potrzebuje żadnego.",
  "No remediation has been planned on this host.": "Na tym hoście nie zaplanowano żadnej naprawy.",
  "No result arrived within the lease; the outcome on the host is unknown.": "Wynik nie przyszedł w czasie dzierżawy; skutek na hoście jest nieznany.",
  "No result within the allowed time; the state of the host is unknown until it reports.": "Brak wyniku w dozwolonym czasie; stan hosta jest nieznany, dopóki nie zaraportuje.",
  "No routes reported.": "Brak zaraportowanych tras.",
  "No rules match.": "Żadna reguła nie pasuje.",
  "No rules yet: the agents sample, but nothing turns the samples into alerts.": "Jeszcze nie ma reguł: agenci próbkują, ale nic nie zamienia próbek w alerty.",
  "No rules.": "Brak reguł.",
  "No sample in this window.": "Brak próbek w tym oknie.",
  "No schedules.": "Brak harmonogramów.",
  "No secret matches the search.": "Żaden sekret nie pasuje do wyszukiwania.",
  "No secret named {name} exists in this installation.": "W tej instalacji nie ma sekretu o nazwie {name}.",
  "No secrets are stored in this installation.": "W tej instalacji nie ma żadnych sekretów.",
  "No service matches the filter.": "Żadna usługa nie pasuje do filtra.",
  "No silence is in force for this host.": "Żadne wyciszenie nie obowiązuje dla tego hosta.",
  "No silence is in force.": "Żadne wyciszenie nie obowiązuje.",
  "No step recorded yet.": "Brak zapisanych kroków.",
  "No such job, or it is out of your scope.": "Nie ma takiego zadania albo jest poza Twoim zakresem.",
  "No sudo rule from the directory reaches this host.": "Żadna reguła sudo z katalogu nie sięga tego hosta.",
  "No sudo rules.": "Brak reguł sudo.",
  "No tag matches the filter.": "Żaden tag nie pasuje do filtra.",
  "No targets.": "Brak celów.",
  "No time servers are configured on this host.": "Na tym hoście nie skonfigurowano serwerów czasu.",
  "No unit is in a failed state.": "Żadna jednostka nie jest w stanie failed.",
  "No vendor advisory names this CVE in the data the panel holds.": "Żadne advisory producenta w danych panelu nie wymienia tego CVE.",
  "No verdict yet: the policy has not been evaluated, or nothing matches the filter.": "Brak werdyktów: polityka nie została oceniona albo nic nie pasuje do filtra.",
  "No {what} were reported the last time this host was read.": "Przy ostatnim odczycie host nie zgłosił: {what}.",
  "Not a budget key: global:mutations, site:warsaw:packages, site:*:reads, domain:rack-1:units, backend:offsite:backup.": "To nie jest klucz budżetu: global:mutations, site:warsaw:packages, site:*:reads, domain:rack-1:units, backend:offsite:backup.",
  "Not a tag: key or key=value, lower-case key.": "To nie jest tag: klucz albo klucz=wartość, klucz małymi literami.",
  "Not applicable": "Nie dotyczy",
  "Not assessed": "Nieocenione",
  "Not established": "Nieustalone",
  "Not evaluated yet.": "Jeszcze nieoceniona.",
  "Not judged": "Nieocenione",
  "Not read": "Nieodczytane",
  "Not reported": "Nie zgłoszono",
  "Not run in time: a task not approved before its expiry, or a campaign whose plans passed their time limit before any host started.": "Nie wykonane na czas: zadanie niezatwierdzone przed wygaśnięciem albo kampania, której plany przekroczyły limit czasu, zanim wystartował jakikolwiek host.",
  "Not shown, no permission: {kinds}": "Nie pokazano, brak uprawnień: {kinds}",
  "Not started": "Nierozpoczęte",
  "Note": "Notatka",
  "Note (at least 8 characters)": "Notatka (co najmniej 8 znaków)",
  "Note (kept in the audit trail)": "Notatka (trafia do audit logu)",
  "Note on {rule} at {host}": "Notatka do {rule} na {host}",
  "Notes": "Uwagi",
  "Nothing happened in that window": "W tym oknie nic się nie wydarzyło",
  "Nothing happens until somebody approves; the approval confirms the plan hash.": "Nic się nie dzieje, dopóki ktoś nie zatwierdzi; zatwierdzenie potwierdza hash planu.",
  "Nothing has been recorded for this host yet.": "Dla tego hosta nie zapisano jeszcze niczego.",
  "Nothing has run for this definition yet.": "Dla tej definicji nic jeszcze nie działało.",
  "Nothing here can be closed by installing an update.": "Niczego tutaj nie zamknie instalacja aktualizacji.",
  "Nothing is checked after the change.": "Po zmianie nic nie jest sprawdzane.",
  "Nothing is firing on the hosts you can see.": "Nic nie alarmuje na hostach, które widzisz.",
  "Nothing is holding a shutdown on this host.": "Nic nie wstrzymuje wyłączenia tego hosta.",
  "Nothing is rolled back by the stop, and there is no way back for this operation.": "Zatrzymanie niczego nie cofa, a ta operacja nie ma drogi powrotu.",
  "Nothing is rolled back by the stop, and there is only a best-effort way back with no guarantee of the previous state.": "Zatrzymanie niczego nie cofa, a droga powrotu jest tylko best effort, bez gwarancji poprzedniego stanu.",
  "Nothing is rolled back by the stop.": "Zatrzymanie niczego nie cofa.",
  "Nothing is rolled back by the stop. A change that landed is undone by a new plan that neutralises it.": "Zatrzymanie niczego nie cofa. Zmianę, która już weszła, odwraca nowy plan, który ją neutralizuje.",
  "Nothing is rolled back by the stop. A host that failed its connectivity check has already reverted itself; a host that committed goes back only with a new plan.": "Zatrzymanie niczego nie cofa. Host, któremu nie przeszedł test łączności, już sam się cofnął; host po commicie wraca tylko nowym planem.",
  "Nothing is rolled back by the stop. The previous version is kept on every host that changed; putting it back is a new plan.": "Zatrzymanie niczego nie cofa. Na każdym zmienionym hoście zachowana jest poprzednia wersja; jej przywrócenie to nowy plan.",
  "Nothing is sent through it until it is enabled again; the events of that time are not sent later.": "Nic nim nie wychodzi do ponownego włączenia; zdarzeń z tego czasu nie dosyła później.",
  "Nothing matched.": "Nic nie pasuje.",
  "Nothing matches the query.": "Nic nie pasuje do zapytania.",
  "Nothing would be removed.": "Nic nie zostałoby usunięte.",
  "Nothing would change on this host.": "Na tym hoście nic by się nie zmieniło.",
  "Nothing you may decide on.": "Nic, o czym możesz decydować.",
  "Nothing; it is promoted by age. Raise the budget if it should not wait.": "Nic; awansuje z czasem. Podnieś budżet, jeśli nie powinno czekać.",
  "Nothing; order again if it is still wanted.": "Nic; zleć ponownie, jeśli nadal potrzebne.",
  "Nothing; the host starts when a token frees up. Raise the budget if it should not wait.": "Nic; host wystartuje, gdy zwolni się token. Podnieś budżet, jeśli nie powinien czekać.",
  "Nothing; the host waits for the other campaign's lock.": "Nic; host czeka na blokadę drugiej kampanii.",
