  "Offline": "Offline",
  "Offline from the directory": "Odcięte od katalogu",
  "Offline policy": "Polityka offline",
  "Offset": "Przesunięcie",
  "Older": "Starsze",
  "Oldest backup": "Najstarsza kopia",
  "Oldest queued": "Najstarsze w kolejce",
  "Oldest transaction": "Najstarsza transakcja",
