  "On boot": "Przy starcie",
  "On the host": "Na hoście",
  "Once the host reported a start, a cancel is only information: the operation runs to its end.": "Gdy host zgłosił start, cancel jest tylko informacją: operacja leci do końca.",
  "One host per line: hostname,fqdn. The hostname is matched to the rows above, full or short; a line that matches no host stays in the box.": "Jeden host na linię: hostname,fqdn. Hostname dopasowywany jest do wierszy powyżej, pełny albo krótki; linia bez dopasowania zostaje w polu.",
  "One host per token. A token for a batch of machines needs the host.enroll.batch permission.": "Jeden host na token. Token dla partii maszyn wymaga uprawnienia host.enroll.batch.",
  "One line will be appended to {path} so chrony reads the panel's sources directory.": "Do {path} zostanie dopisana jedna linia, by chrony czytał katalog źródeł panelu.",
  "One per line or comma-separated; at most twenty.": "Po jednym w linii albo po przecinku; najwyżej dwadzieścia.",
  "One public key as it goes into the file: the type, the material and an optional comment. It is appended; the keys above stay as they are.": "Jeden klucz publiczny w postaci, w jakiej trafia do pliku: typ, materiał i opcjonalny komentarz. Jest dopisywany; klucze powyżej zostają bez zmian.",
  "One public key per line. What is not on the list is gone from the file; an empty list revokes key access to it.": "Jeden klucz publiczny w linii. Czego nie ma na liście, znika z pliku; pusta lista odbiera dostęp kluczem do tego pliku.",
  "One row is one shape of the change and the hosts that get it. A host whose plan changed since refuses the change.": "Jeden wiersz to jedna postać zmiany i hosty, które ją dostaną. Host, którego plan zmienił się od tego czasu, odmówi zmiany.",
  "One row per CVE across the hosts you can see, the gravest and the most widespread first. The host count is the number of machines to move; the fix count says on how many of them the vendor has released one.": "Jeden wiersz na CVE w obrębie widocznych hostów, najpierw najpoważniejsze i najszerzej rozsiane. Liczba hostów to liczba maszyn do ruszenia; liczba poprawek mówi, na ilu z nich producent już ją wydał.",
  "One row per event and channel, newest first. A receiver that is down delays a message rather than losing it: the row waits, the attempts are counted on it, and a message nobody received ends as a dead letter an operator sends again.": "Jeden wiersz na zdarzenie i kanał, od najnowszych. Odbiorca, który leży, opóźnia wiadomość, a nie gubi ją: wiersz czeka, próby są liczone na nim, a wiadomość, której nikt nie odebrał, kończy jako dead letter, którą operator wysyła ponownie.",
  "One row per package per host; a host with two vulnerable packages stands twice. The state is the vendor's answer for that package on that host.": "Jeden wiersz na pakiet na host; host z dwoma podatnymi pakietami występuje dwa razy. Stan to odpowiedź producenta dla tego pakietu na tym hoście.",
  "One unit per line or comma-separated, e.g. nginx.service. Checked on every host right after the change, or after the reboot when one follows; empty means nothing is verified.": "Jeden unit na linię albo po przecinku, np. nginx.service. Sprawdzane na każdym hoście zaraz po zmianie, a po reboocie, jeśli taki następuje; puste znaczy brak weryfikacji.",
  "Online": "Online",
  "Only entries owned by Flotestro can be run from the panel.": "Z panelu można uruchamiać tylko wpisy należące do Flotestro.",
  "Only paths on the host's allowlist can be read, and symlinks are not followed.": "Można czytać tylko ścieżki z allowlisty hosta, a dowiązania symboliczne nie są podążane.",
  "Only reads the registry opens to a fan-out are listed.": "Na liście są tylko odczyty, które rejestr dopuszcza do fan-outu.",
  "Only rules owned by Flotestro": "Tylko reguły należące do Flotestro",
  "Only the closest {n} certificates are listed. The counts above cover all of them.": "Wypisano tylko {n} najbliższych certyfikatów. Liczby powyżej obejmują wszystkie.",
  "Only the person who ordered the reset may read the password.": "Hasło może odczytać tylko osoba, która zleciła reset.",
  "Only what needs a decision.": "Tylko to, co wymaga decyzji.",
  "Only whoever manages access can add a mapping; ask an administrator.": "Mapowanie może dodać tylko ktoś zarządzający dostępem; poproś administratora.",
