  "OpenAPI": "OpenAPI",
  "Opens the Bulk workspace with the same operation, name and payload written in; the targets and the rollout are chosen again.": "Otwiera Bulk workspace z wpisaną tą samą operacją, nazwą i payloadem; targety i rollout wybierasz od nowa.",
  "Opens the Bulk workspace with the same operation, payload and host written in.": "Otwiera workspace Bulk z tą samą operacją, payloadem i hostem już wpisanymi.",
  "Operating system": "System operacyjny",
  "Operation": "Operacja",
  "Operations": "Operacje",
  "Operations cut short": "Przerwane operacje",
  "Operations, last 24 h": "Operacje, ostatnie 24 h",
  "Operator": "Operator",
  "Operators sign in through the company's identity provider (Keycloak, Entra, any OpenID Connect issuer), so leaving the company means leaving the panel, and every action in the trail carries a real name. Without it the panel takes API tokens alone.": "Operatorzy logują się przez firmowego dostawcę tożsamości (Keycloak, Entra, dowolny issuer OpenID Connect), więc odejście z firmy oznacza utratę dostępu do panelu, a każda akcja w śladzie audytowym ma prawdziwe nazwisko. Bez niego panel przyjmuje wyłącznie tokeny API.",
  "Optional": "Opcjonalne",
  "Optional for an approval; the second approver of a destructive operation reads it.": "Opcjonalny przy zatwierdzeniu; czyta go drugi zatwierdzający operacji destrukcyjnej.",
  "Optional here; a critical operation requires at least {n} characters.": "Tu opcjonalne; operacja krytyczna wymaga co najmniej {n} znaków.",
  "Optional with a recurrence: the earliest moment the rule may name.": "Opcjonalne przy regule powtarzania: najwcześniejszy termin, jaki reguła może wskazać.",
  "Optional: the identifier or address of the change request.": "Opcjonalnie: identyfikator albo adres wniosku o zmianę.",
  "Optional; hosts wait until then. Local time.": "Opcjonalne; hosty czekają do tej chwili. Czas lokalny.",
  "Optional; it goes to the audit log next to the order.": "Opcjonalnie; trafia do audit logu obok zlecenia.",
  "Optional; kept in the audit trail.": "Opcjonalnie; zostaje w audycie.",
  "Optional; no host is started once it closes - a host still waiting stays held back, and a host still rebooting fails and pauses the campaign.": "Opcjonalne; po zamknięciu okna żaden host już nie startuje - host w kolejce dalej czeka, a host w trakcie reboota kończy błędem i pauzuje kampanię.",
  "Optional; set on every host the same. The static name comes from the mapping below.": "Opcjonalna; ustawiana tak samo na każdym hoście. Nazwa statyczna pochodzi z mapowania poniżej.",
  "Optional; the answer must contain it.": "Opcjonalne; odpowiedź musi go zawierać.",
  "Optional; the directory server to talk to instead of the one DNS names.": "Opcjonalne; serwer katalogu zamiast tego, który wskazuje DNS.",
  "Optional; the rules below narrow it further.": "Opcjonalnie; reguły poniżej zawężają ją dalej.",
  "Optional; what hostnamectl shows to people.": "Opcjonalna; to, co hostnamectl pokazuje ludziom.",
