  "Paste a job identifier to read what the host wrote while that operation ran.": "Wklej identyfikator zadania, żeby odczytać, co host zapisał w czasie tej operacji.",
  "Paste as CSV": "Wklej jako CSV",
  "Paste the certificate with its chain, leaf first. The private key is not pasted here and never travels in the job: the host fetches it from the secret named on the watched path, once, while it runs the operation.": "Wklej certyfikat z łańcuchem, liść pierwszy. Klucza prywatnego nie wkleja się tutaj i nigdy nie jedzie w zadaniu: host pobiera go z sekretu wskazanego przy obserwowanej ścieżce, raz, w trakcie operacji.",
