  "Privileged: {groups}. An account created straight into such a group is root by another name; the order needs the permission accounts.privileged_groups beside localuser.create, ranks critical and asks for fresh authentication and an approval.": "Uprzywilejowane: {groups}. Konto zakładane od razu w takiej grupie to root pod inną nazwą; zlecenie wymaga uprawnienia accounts.privileged_groups obok localuser.create, ma rangę krytyczną i prosi o świeże uwierzytelnienie oraz zatwierdzenie.",
