  "Read from the kernel with nft. Flotestro owns one table of its own — docker, firewalld and iptables-nft rewrite theirs without asking, so a rule placed in those would vanish at the next container start or reload.": "Odczyt z jądra przez nft. Flotestro ma jedną własną tablicę — docker, firewalld i iptables-nft przepisują swoje bez pytania, więc reguła wstawiona tam zniknęłaby przy następnym starcie kontenera albo przeładowaniu.",
  "Read from the kernel, not from configuration files: what the host has up and what someone once wrote into a config file can differ.": "Odczyt z jądra, nie z plików konfiguracyjnych: to, co host ma podniesione, i to, co ktoś kiedyś wpisał do konfiguracji, może się różnić.",
