  "Required here: a production environment, a batch token or a relay is a change the audit trail keeps the reason of. At least 8 characters.": "Tu wymagany: środowisko produkcyjne, token partii albo relay to zmiana, której powód zostaje w audycie. Co najmniej 8 znaków.",
  "Required level (acr)": "Wymagany poziom (acr)",
