  "Rotating…": "Rotacja…",
  "Rotation in four stages, each an ordinary campaign: distribute the new authority, verify it reached every host, rotate the leaves, withdraw the old authority. A withdrawal is refused while any host is unverified or still holds a certificate issued by it.": "Rotacja w czterech etapach, każdy to zwykła kampania: rozdaj nowy urząd, sprawdź, że dotarł do każdego hosta, obróć certyfikaty końcowe, wycofaj stary urząd. Wycofanie jest odrzucane, dopóki jakikolwiek host jest niezweryfikowany albo nadal ma certyfikat wystawiony przez ten urząd.",
