  "SELinux on {host} starts enforcing its policy now and after reboot. A process the policy does not cover is denied from this moment.": "SELinux na {host} zaczyna wymuszać politykę teraz i po restarcie. Proces, którego polityka nie obejmuje, od tej chwili dostaje odmowę.",
  "SELinux on {host} stops enforcing its policy, now and after reboot: denials are only logged. Coming back is another order, not a reboot.": "SELinux na {host} przestaje wymuszać politykę, teraz i po restarcie: odmowy są tylko logowane. Powrót to osobne zlecenie, nie restart.",
  "SHA-256 fingerprint of the signing CA; compare it with what openssl prints on the host.": "Odcisk SHA-256 podpisującego CA; porównaj z tym, co openssl wypisze na hoście.",
