  "Showing 60 of {n} modules; narrow the filter to see the rest.": "Pokazano 60 z {n} modułów; zawęź filtr, by zobaczyć resztę.",
  "Showing the first {count} of each kind; a longer query narrows the rest.": "Pokazuję pierwsze {count} z każdego rodzaju; dłuższe zapytanie zawęzi resztę.",
  "Showing the first {shown} of {n}. The counts above cover all of them.": "Pokazano pierwsze {shown} z {n}. Liczniki wyżej obejmują wszystkie.",
  "Showing {shown} of {total} processes. Change the sort order to see a different slice.": "Pokazano {shown} z {total} procesów. Zmień sortowanie, by zobaczyć inny wycinek.",
  "Shown once. Paste it into the hidden prompt on the host; do not put it in a shell command — the command line is visible to every user of that machine.": "Pokazany tylko raz. Wklej go w ukrytym prompcie na hoście; nie wpisuj go w wiersz poleceń — linię poleceń widzi każdy użytkownik tej maszyny.",
