  "Site {site} has no relay; the host connects directly.": "Lokalizacja {site} nie ma relaya; host łączy się bezpośrednio.",
  "Site {site} · environment {environment} · token expires": "Lokalizacja {site} · środowisko {environment} · token wygasa",
  "Site {site}. A relay attests the identity of the hosts behind it to the panel, so what it reports about itself is what the panel knows about the site.": "Lokalizacja {site}. Relay poświadcza panelowi tożsamość hostów za sobą, więc to, co zgłasza o sobie, jest tym, co panel wie o lokalizacji.",
  "Site, environment and OS family, set in the next step.": "Site, środowisko i rodzina OS, ustawiane w następnym kroku.",
