  "Slack-compatible webhook": "Webhook zgodny ze Slackiem",
  "Smaller text and denser layout": "Mniejszy tekst i gęstszy układ",
  "Sockets listening beyond the loopback interface. Each one is a way into this host for anyone who can see its network.": "Gniazda nasłuchujące poza interfejsem loopback. Każde z nich to droga do tego hosta dla każdego, kto widzi jego sieć.",
  "Soft-deleted entries: the UID and the trail stay, nobody signs in. They are listed apart so they are not counted as users.": "Wpisy usunięte miękko: UID i ślad zostają, nikt się nie loguje. Są wypisane osobno, żeby nie liczyć ich jako użytkowników.",
  "Some of the change landed and some did not; the result lists both.": "Część zmiany weszła, część nie; wynik wymienia jedno i drugie.",
  "Somebody changed this host since you opened the editor; close it and open it again to see the current value.": "Ktoś zmienił tego hosta, odkąd otworzyłeś edytor; zamknij go i otwórz ponownie, żeby zobaczyć bieżącą wartość.",
  "Sort": "Sortowanie",
  "Sorted from the nearest deadline; a heading reorders the listed rows.": "Od najbliższego terminu; kliknięcie nagłówka zmienia kolejność wyświetlonych wierszy.",
