  "Steps run one after another: each is an ordinary job of the module that owns it, and the next one starts only once the previous succeeded. A step that needs a reboot ends the plan — what comes after a reboot has to be judged against the host that came back.": "Kroki idą jeden po drugim: każdy to zwykłe zadanie modułu, który za nie odpowiada, a kolejny rusza dopiero po sukcesie poprzedniego. Krok wymagający restartu kończy plan — to, co po restarcie, trzeba ocenić wobec hosta, który wrócił.",
