  "Taken by a scheduler; delivery to the host is under way.": "Wzięte przez scheduler; dostarczanie do hosta w toku.",
  "Taken off the hosts that carry them; the others are left as they are.": "Zdejmowane z hostów, które je mają; pozostałe zostają bez zmian.",
  "Target": "Cel",
  "Target agent version (currently {version})": "Docelowa wersja agenta (obecnie {version})",
