  "Writing the whole list anew is a critical change of access: at least 8 characters, recorded with the order.": "Zapisanie całej listy od nowa to krytyczna zmiana dostępu: co najmniej 8 znaków, zapisywane razem ze zleceniem.",
  "Written": "Zapisany",
  "You approve exactly this payload for {operation} on {host}; the consent is bound to hash {hash}.": "Zatwierdzasz dokładnie ten payload dla {operation} na {host}; zgoda jest związana z hashem {hash}.",
  "You are approving this operation, this payload, this list of hosts, this rollout policy and this set of plans - together, as one fingerprint.": "Zatwierdzasz tę operację, ten payload, tę listę hostów, tę politykę rozwijania i ten zestaw planów — razem, jako jeden odcisk.",
  "You do not have permission to manage access.": "Nie masz uprawnień do zarządzania dostępem.",
  "You do not have permission to read the directory.": "Nie masz uprawnień do odczytu katalogu.",
  "You do not have permission to read the fleet-wide audit trail. A single host's audit trail is available in its own view.": "Nie masz uprawnień do odczytu audytu całej floty. Audyt pojedynczego hosta jest dostępny w jego widoku.",
  "You do not have permission to read this host's accounts.": "Nie masz uprawnień do odczytu kont tego hosta.",
