  "You do not have permission to view this.": "Brak uprawnień do tego widoku.",
  "You may not change this budget: a site budget needs the right in its site, the rest in the whole fleet.": "Nie możesz zmienić tego budżetu: budżet lokalizacji wymaga uprawnienia w jej zakresie, pozostałe w całej flocie.",
  "Your identity provider may sign you in with an account you already have an open session for.": "Dostawca tożsamości może zalogować Cię na konto, na którym masz już otwartą sesję.",
  "Your reads": "Twoje odczyty",
