  "Zones": "Strefy",
  "Zones and records live in the directory, not in anyone's /etc/hosts. A record here answers for the whole network, so it goes the same way as a directory account: plan first, then approval, then execution — and the reverse record is a separate, visible step of that plan.": "Strefy i rekordy żyją w katalogu, nie w czyimś /etc/hosts. Rekord tutaj odpowiada całej sieci, więc idzie tą samą drogą co konto katalogowe: najpierw plan, potem zgoda, potem wykonanie — a rekord odwrotny jest osobnym, widocznym krokiem tego planu.",
